def renal_name(step):
    return {1.0:"renal impairment / early acute kidney injury (creatinine borderline)",1.5:"acute kidney injury (creatinine rise, KDIGO stage 1)",2.0:"acute kidney injury (creatinine ~2x baseline, KDIGO stage 2)"}[step]
out={}
for stay,(rp,items) in R.items():
    for step,p in rp.items():
        lst=[{"name":n,"probability":q} for n,q in items]+[{"name":renal_name(step),"probability":p}]
        lst.sort(key=lambda x:-x["probability"])
        out[f"{stay}@{step}"]=lst[:10]
keys={f"{p['stay']}@{p['ladder']}" for p in json.load(open("eval/blackbox/panels_P4_monotonic.json"))}
assert keys==set(out), keys^set(out)
json.dump(out,open("eval/blackbox/reads_llm_P4_monotonic.json","w"),indent=0)
print(len(out))
